// 점수 → 표현 구간. AI는 이 구간 표현과 같은 방향으로만 서술한다.
function band(score: number, low: string, mid: string, high: string): string {
  return score >= 70 ? high : score >= 40 ? mid : low;
}

function chunk<T>(arr: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

// One generation call for a slice of categories. Chunked + parallel so the
// full 12-13 category long-form report fits serverless time limits.
async function callChunk(
  c: AnthropicLike,
  system: string,
  context: string,
  cats: ReportCategory[],
  allCats: ReportCategory[],
  startNo: number,
  lang: Lang
): Promise<Array<{ title: string; body: string }> | null> {
  const prompt =
    context +
    `\n\n전체 리포트의 카테고리 구성 (겹치면 안 되는 다른 주제들):\n` +
    allCats.map((t, i) => `${i + 1}. ${t.label}`).join(" / ") +
    `\n\n이번엔 다음 카테고리만 작성해줘:\n` +
    cats.map((t, i) => `${startNo + i}. [${t.label}] ${t.spec}`).join("\n") +
    `\n\n범위 규칙: 위 [라벨]의 spec 범위 안에서만 써라. 전체 구성에 있는 다른 카테고리의 ` +
    `주제는 여기서 한 문장도 다루지 마라 (예: 겉궁합에서 속궁합 얘기 금지, 결혼운에서 돈 얘기 금지). ` +
    `\n\n${LENGTH_RULE}\n\n출력은 반드시 JSON 배열만: [{"title":"...","body":"..."}] — ` +
    `title은 반드시 "<카테고리명> — <감성 부제>" 형식 (카테고리명은 [라벨]을 ${LANG_NAME[lang]}로, ` +
    `부제는 이 커플만의 한 줄). 번호는 붙이지 마라. body는 본문. ` +
    `모든 텍스트는 ${LANG_NAME[lang]}(으)로.`;
  try {
    const res = await c.messages.create({
      model: MODEL,
      max_tokens: 4096,
      system: [{ type: "text", text: system, cache_control: { type: "ephemeral" } }],
      messages: [{ role: "user", content: prompt }],
    });
    const text = res.content.find((b) => b.type === "text")?.text ?? "";
    const json = text.slice(text.indexOf("["), text.lastIndexOf("]") + 1);
    const parsed = JSON.parse(json) as Array<{ title: string; body: string }>;
    if (!Array.isArray(parsed) || parsed.length === 0) return null;
    const out = parsed.map((sec) => ({
      title: String(sec.title ?? "").slice(0, 120),
      body: String(sec.body ?? ""),
    }));
    // Reject degenerate output — a rare "placeholder" stub, an empty body, or a
    // section far shorter than the length rule asks for. Returning null lets the
    // caller's retry loop regenerate this part instead of saving junk.
    if (out.some((s) => s.body.trim().length < 120 || s.body.trim() === s.title.trim())) {
      return null;
    }
    if (out.some((s) => wrongLanguage(s.title + " " + s.body, lang))) {
      console.warn("report chunk in wrong language — retrying");
      return null;
    }
    return out;
  } catch (err) {
    console.error("report chunk generation failed:", err);
    return null;
  }
}

const THAI_NAMING =
  ` 태국어 표기 규칙: 지지는 한자 음역(เจี๊ยะ·ฮว่าย·แก้ 등)을 쓰지 말고 태국 12지 이름으로 ` +
  `(子ชวด 丑ฉลู 寅ขาล 卯เถาะ 辰มะโรง 巳มะเส็ง 午มะเมีย 未มะแม 申วอก 酉ระกา 戌จอ 亥กุน), ` +
  `천간은 오행으로 풀어 써라(예: 丙 = ไฟหยาง/ดวงอาทิตย์). 간지 한자는 괄호 안에만 둔다. ` +
  `한국어 문장·한국어 제목을 쓰지 마라(명리 용어는 괄호 안 한글 1~2단어만 허용).`;

// 언어별 표기 규칙: 본문에 한자만 덩그러니 쓰지 않고 각 언어로 풀어 쓴다.
function scriptRules(lang: Lang): string {
  if (lang === "th") return THAI_NAMING +
    ` 십신·신살·12운성도 태국어 뜻으로 풀어 써라(예: 식신 → ดาวแห่งการสร้างสรรค์, 백호살 → ดาวเสือขาว, 천을귀인 → ดาวผู้อุปถัมภ์). ` +
    `한자(丙戌·食神·白虎殺 등)를 문장 안에 단독으로 쓰지 마라. 꼭 필요하면 태국어 뒤 괄호 안에 섹션당 1회만.`;
  if (lang === "en") return ` Script rule: write every term in English (e.g. "Byeong-sul day pillar", "Output star (Siksin)", "White Tiger star"). ` +
    `Never drop bare Chinese characters (丙戌, 食神, 白虎殺) into a sentence; at most once per section in parentheses after the English.`;
  return ` 한자 표기 규칙: 본문은 한글로 쓴다. 간지·십신·신살은 한글로(병술 일주, 계해 월주, 식신, 일지, 백호살, 화개살, 천을귀인). ` +
    `한자를 단독으로 쓰지 마라(丙戌 일주 ✗, 食神 ✗, 白虎殺 ✗ → 병술 일주, 식신, 백호살). 꼭 필요하면 한글 뒤 괄호 안에 섹션당 처음 1회만(예: 병술(丙戌)).`;
}

// 괄호 밖에 한자가 많이 남은 섹션은 재시도시킨다.
function tooMuchHanja(text: string): boolean {
  const outside = text.replace(/\([^)]*\)/g, "");
  return (outside.match(/[\u4E00-\u9FFF]/g) ?? []).length > 6;
}

// 출력 언어 검사: 다른 언어(특히 한국어)로 써버린 섹션은 버리고 재시도시킨다.
function wrongLanguage(text: string, lang: Lang): boolean {
  if (tooMuchHanja(text)) return true;
  const letters = text.replace(/[\s\d\p{P}\p{S}]/gu, "");
  if (!letters) return true;
  const hangul = (letters.match(/[\uAC00-\uD7A3]/g) ?? []).length;
  const thai = (letters.match(/[\u0E00-\u0E7F]/g) ?? []).length;
  if (lang === "th") return thai / letters.length < 0.5 || hangul / letters.length > 0.12;
  if (lang === "en") return hangul / letters.length > 0.12 || thai / letters.length > 0.12;
  return hangul / letters.length < 0.3; // ko
}

/**
 * Translate ONE generated section into another language, preserving meaning,
 * length, paragraph breaks, and emoji — so every language shows the same
 * report. Client-orchestrated one call per section (like generation).
 */
export async function translateSection(
  title: string,
  body: string,
  lang: Lang
): Promise<{ title: string; body: string } | null> {
  const c = getClient();
  if (!c) return null;
  const prompt =
    `다음 사주 해석 섹션을 ${LANG_NAME[lang]}(으)로 번역해줘. ` +
    `의미와 정보량, 문단 구분(빈 줄), 이모지를 그대로 유지하고, ` +
    `명리 용어는 ${LANG_NAME[lang]} 독자가 이해할 수 있게 자연스럽게 옮겨라. 요약하거나 줄이지 마라.` + scriptRules(lang) + ` ` +
    `출력은 반드시 JSON 하나만: {"title":"...","body":"..."}\n\n` +
    `[제목] ${title}\n[본문]\n${body}`;
  try {
    const res = await c.messages.create({
      model: MODEL,
      max_tokens: 3000,
      messages: [{ role: "user", content: prompt }],
    });
    const text = res.content.find((b) => b.type === "text")?.text ?? "";
    const json = text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1);
    const p = JSON.parse(json) as { title: string; body: string };
    if (!p?.title || !p?.body) return null;
    // Reject a degenerate/placeholder translation so the retry loop re-runs it.
    if (String(p.body).trim().length < 120) return null;
    if (wrongLanguage(String(p.title) + " " + String(p.body), lang)) return null;
    return { title: String(p.title).slice(0, 200), body: String(p.body) };
  } catch (err) {
    console.error("section translation failed:", err);
    return null;
  }
}

const READING_CATEGORIES: ReportCategory[] = [
  { label: "원국 총평", spec: "오행 흐름과 그릇의 크기, 시적인 비유 포함. 총론만." },
  { label: "성격", spec: "타고난 성격의 빛과 그림자만." },
  { label: "연애운", spec: "끌리는 상대의 기운, 사랑하는 방식, 주의점만." },
  { label: "결혼운", spec: "어울리는 배우자상과 결혼 생활의 모습만." },
  { label: "직업·적성", spec: "기운에 맞는 일과 피해야 할 일만." },
  { label: "재물운", spec: "돈이 들어오는 길과 새는 구멍만." },
  { label: "건강운", spec: "약한 오행과 몸 관리 포인트만." },
  { label: "인간관계", spec: "나를 돕는 귀인의 기운과 관계 패턴만." },
  { label: "대운 흐름", spec: "[검증된 사실]의 대운 목록과 현재 대운만 근거로 10년 단위 인생 리듬. 대운 간지를 실제로 인용하고, 계산 불가면 간지 언급 없이 일반적 흐름만." },
  { label: "올해·내년", spec: "[검증된 사실]의 세운 간지(올해·내년)를 일간과의 관계로 풀어 올해와 내년 운만." },
  { label: "개운법", spec: "[검증된 사실]의 보완 오행 기준 행운 컬러·숫자·방향·습관 + 추천 아이템(오행 팔찌 원석, 오행 블렌드 티)을 생활 루틴으로 자연스럽게 제안. 효능·치료 표현 금지(라이프스타일 표현만)." },
  { label: "마무리", spec: "짧은 마무리 총평. 이 사람만의 개운 문구 한 줄 포함." },
];

const CHUNK_SIZE = 1;

function readingPrompt(
  chart: SajuChart,
  profile: { name?: string; gender?: string },
  lang: Lang
): { system: string; context: string } {
  const s = analyzeStrength(chart, lang);
  const name = profile.name || (lang === "ko" ? "이 분" : lang === "th" ? "เจ้าชะตา" : "this person");
  const system =
    `너는 20년 경력의 명리학(사주) 상담가이자 감성 카피라이터다. ` +
    `따뜻하고 다정하며, 명리 용어(상생·조후·용신·억부·합·충 등)를 자연스럽게 녹여 ` +
    `근거 있는 해석을 쓴다. 단정적 협박은 금지, 실용적 조언 포함. ` +
    `반드시 ${LANG_NAME[lang]}(으)로만 작성한다.` +
    scriptRules(lang);
  const sinsal = findSinsal(chart);
  const context =
    `사주 풀이 리포트를 작성해줘.\n\n` +
    `[의뢰인] ${name} (${profile.gender === "F" ? "여" : profile.gender === "M" ? "남" : "성별 미상"})\n` +
    `사주: ${pillarsOf(chart)}\n` +
    `일간: ${chart.dayMaster} / 오행 분포: ${JSON.stringify(chart.elementCounts)}\n` +
    `신강약: ${s.bandLabel} (내부 지표, 숫자는 본문에 쓰지 말 것: ${s.supportRatio.toFixed(2)}) / 용신: ${s.favorable.join(", ")}\n` +
    `신살: ${sinsal.length ? sinsal.join(", ") : "없음"} (도화=매력, 홍염=달콤한 유혹, 화개=예술·고독, 역마=이동·변화 — 있으면 해석에 반드시 반영)\n` +
    `분석 노트: ${s.notes.join(" | ") || "없음"}\n\n` +
    `[검증된 사실 — 엔진 계산값. 십신·12운성·신살·대운·세운은 여기 있는 것만 인용]\n` +
    factSheet(chart, {
      gender: profile.gender,
      birth: { year: chart.solarUsed.y, month: chart.solarUsed.m, day: chart.solarUsed.d },
    }) +
    `\n${remedyFactPersonal(chart)}` +
    `\n\n호칭 규칙: 의뢰인은 반드시 "${name}"(으)로 지칭하고, A나 '고객' 같은 임의 약칭을 만들지 마라. ` +
    `나이를 자연스럽게 활용하라(예: "${name}님은 지금 서른 즈음의…").` +
    ACCURACY_RULES;
  return { system, context };
}

/** Number of generation parts for a report (client orchestrates one call per part). */
export function reportChunkCount(kind: "reading" | "compat", relationship?: string): number {
  const cats =
    kind === "reading"
      ? READING_CATEGORIES
      : ROMANTIC.has(relationship ?? "lovers")
      ? ROMANTIC_CATEGORIES
      : PLATONIC_CATEGORIES;
  return Math.ceil(cats.length / CHUNK_SIZE);
}

/** Generate ONE part (3 categories) of the reading report — fits any timeout. */
export async function generateReadingPart(
  chart: SajuChart,
  profile: { name?: string; gender?: string },
  lang: Lang,
  part: number
): Promise<Array<{ title: string; body: string }> | null> {
  const c = getClient();
  if (!c) return null;
  const chunks = chunk(READING_CATEGORIES, CHUNK_SIZE);
  if (part < 0 || part >= chunks.length) return null;
  const { system, context } = readingPrompt(chart, profile, lang);
  return callChunk(c, system, context, chunks[part], READING_CATEGORIES, part * CHUNK_SIZE + 1, lang);
}

/**
 * Long-form paid saju reading (~12 titled sections). Returns null when no API
 * key is set or generation fails — callers keep the static template unlock.
 */
export async function generateReadingReport(
  chart: SajuChart,
  profile: { name?: string; gender?: string },
  lang: Lang
): Promise<ReportSection[] | null> {
  const c = getClient();
  if (!c) return null;

  const { system, context } = readingPrompt(chart, profile, lang);
  const chunks = chunk(READING_CATEGORIES, CHUNK_SIZE);
  let start = 1;
  const jobs = chunks.map((cs) => {
    const job = callChunk(c, system, context, cs, READING_CATEGORIES, start, lang);
    start += cs.length;
    return job;
  });
  const results = await Promise.all(jobs);
  const all = results.filter(Boolean).flat() as Array<{ title: string; body: string }>;
  if (all.length < READING_CATEGORIES.length) return null; // full report or nothing
  return all.map((sec, i) => ({
    key: `gen${i + 1}`,
    title: sec.title,
    body: sec.body,
    locked: false,
  }));
}

// The engine's factual cross-chart combination list (positions included) —
// the ONLY 합/암합/충 the AI may cite. Old stored results lack `combos`.
function comboList(result: Compatibility, nameA: string, nameB: string): string {
  const list = (result.combos ?? [])
    .map((c) => `- ${c.replaceAll("{A}", nameA).replaceAll("{B}", nameB)}`)
    .join("\n");
  if (!list) return "";
  return (
    `\n\n[확인된 합·충 목록 — 위치까지 검증된 사실. 합·암합·우합·삼합·충은 이 목록에 있는 것만, ` +
    `적힌 위치 그대로 언급하라. 목록에 없는 합을 지어내면 안 된다]\n${list}`
  );
}

function compatPrompt(
  chartA: SajuChart,
  chartB: SajuChart,
  profiles: { a?: { name?: string; gender?: string }; b?: { name?: string; gender?: string } },
  result: Compatibility
): { system: string; context: string; cats: ReportCategory[]; lang: Lang } {
  const lang = result.lang ?? "th";
  const relationship = result.relationship ?? "lovers";
  const romantic = ROMANTIC.has(relationship);
  // Refer to people by their entered name; fall back to a gendered label —
  // never "A"/"B".
  const personLabel = (
    p: { name?: string; gender?: string } | undefined,
    ord: number
  ): string => {
    if (p?.name?.trim()) return p.name.trim();
    if (p?.gender === "F") return lang === "ko" ? "여자분" : lang === "th" ? "ฝ่ายหญิง" : "the woman";
    if (p?.gender === "M") return lang === "ko" ? "남자분" : lang === "th" ? "ฝ่ายชาย" : "the man";
    return lang === "ko" ? `${ord === 1 ? "첫" : "두"} 번째 분` : lang === "th" ? `คนที่ ${ord}` : `person ${ord}`;
  };
  const nameA = personLabel(profiles.a, 1);
  const nameB = personLabel(profiles.b, 2);

  const system =
    `너는 20년 경력의 명리학(사주) 상담가이자 감성 카피라이터다. ` +
    `따뜻하고 다정하며, 명리 용어(상생·조후·용신·합·충 등)를 자연스럽게 녹여 ` +
    `근거 있는 해석을 쓴다. 단정적 협박은 금지, 실용적 조언 포함. ` +
    `반드시 ${LANG_NAME[lang]}(으)로만 작성한다.` +
    scriptRules(lang);

  // Engine findings (배우자성·천을귀인·신살·암합·조후…) — the long report must
  // build on these, not contradict them.
  const points = (result.sections ?? [])
    .filter((s) => s.key.startsWith("note"))
    .map((s) => `- ${s.title ? s.title + ": " : ""}${s.body}`)
    .join("\n");
  const sinsalLine = (c: SajuChart) => {
    const ss = findSinsal(c);
    return ss.length ? ss.join(", ") : "없음";
  };
  const context =
    `두 사람의 궁합 리포트를 작성해줘.\n\n` +
    `[${nameA}] (${profiles.a?.gender === "F" ? "여" : profiles.a?.gender === "M" ? "남" : "성별 미상"})\n` +
    `사주: ${pillarsOf(chartA)}\n오행 분포: ${JSON.stringify(chartA.elementCounts)}\n신살: ${sinsalLine(chartA)}\n\n` +
    `[${nameB}] (${profiles.b?.gender === "F" ? "여" : profiles.b?.gender === "M" ? "남" : "성별 미상"})\n` +
    `사주: ${pillarsOf(chartB)}\n오행 분포: ${JSON.stringify(chartB.elementCounts)}\n신살: ${sinsalLine(chartB)}\n\n` +
    `[검증된 사실 — ${nameA}]\n` +
    factSheet(chartA, { gender: profiles.a?.gender, birth: birthOf(chartA) }) +
    `\n\n[검증된 사실 — ${nameB}]\n` +
    factSheet(chartB, { gender: profiles.b?.gender, birth: birthOf(chartB) }) +
    `\n${remedyFactCouple(chartA, chartB, nameA, nameB)}` +
    `\n나이 차이: ${Math.abs(ageOn(birthOf(chartA)) - ageOn(birthOf(chartB)))}살 — 관계 해석에 자연스럽게 활용하라.\n\n` +
    `관계: ${relationship} / 궁합 점수: ${result.score}% → 표현 방향: ` +
    band(result.score, "노력으로 완성해가는 인연", "편안하게 맞춰가는 인연", "서로 강하게 끌리는 인연") +
    (romantic && typeof result.intimate === "number"
      ? ` / 속궁합: ${result.intimate}% → 표현 방향: ` +
        band(result.intimate, "천천히 데워지는 온도", "따뜻하고 안정적인 온도", "뜨겁게 통하는 온도")
      : "") +
    `\n(위 '표현 방향'과 반대되는 서술 금지)` +
    (points
      ? `\n\n[엔진 분석 포인트 — 배우자성(관성·재성)·천을귀인·신살·암합 등. 반드시 이 근거들을 해석에 녹여라]\n${points}`
      : "") +
    comboList(result, nameA, nameB) +
    `\n\n호칭 규칙: 두 사람은 반드시 "${nameA}"와(과) "${nameB}"로만 지칭하라. ` +
    `"A", "B", "사람1" 같은 임의 약칭을 절대 만들지 마라.` +
    ACCURACY_RULES;

  return { system, context, cats: romantic ? ROMANTIC_CATEGORIES : PLATONIC_CATEGORIES, lang };
}

/** Generate ONE part (3 categories) of the compat report — fits any timeout. */
export async function generateCompatPart(
  chartA: SajuChart,
  chartB: SajuChart,
  profiles: { a?: { name?: string; gender?: string }; b?: { name?: string; gender?: string } },
  result: Compatibility,
  part: number
): Promise<Array<{ title: string; body: string }> | null> {
  const c = getClient();
  if (!c) return null;
  const { system, context, cats, lang } = compatPrompt(chartA, chartB, profiles, result);
  const chunks = chunk(cats, CHUNK_SIZE);
  if (part < 0 || part >= chunks.length) return null;
  return callChunk(c, system, context, chunks[part], cats, part * CHUNK_SIZE + 1, lang);
}

/**
 * Generate the long-form paid report. Returns null when no API key is set or
 * generation fails — callers fall back to the static template unlock.
 */
export async function generateCompatReport(
  chartA: SajuChart,
  chartB: SajuChart,
  profiles: { a?: { name?: string; gender?: string }; b?: { name?: string; gender?: string } },
  result: Compatibility
): Promise<CompatSection[] | null> {
  const c = getClient();
  if (!c) return null;

  const { system, context, cats, lang } = compatPrompt(chartA, chartB, profiles, result);
  const chunks = chunk(cats, CHUNK_SIZE);
  let start = 1;
  const jobs = chunks.map((cs) => {
    const job = callChunk(c, system, context, cs, cats, start, lang);
    start += cs.length;
    return job;
  });
  const results = await Promise.all(jobs);
  const all = results.filter(Boolean).flat() as Array<{ title: string; body: string }>;
  if (all.length < cats.length) return null; // full report or nothing
  return all.map((sec, i) => ({
    key: `gen${i + 1}`,
    title: sec.title,
    body: sec.body,
    locked: false,
  }));
}
